var n=`0083-mititei`;var t=`world-0083`;var a=`RO`;var r=`eastern-europe`;var l=4;var o=74;var s={en:`Mititei`,ua:`Мітітей`};var d={en:`A classic dish from Romania, featuring ground beef, garlic, baking soda, sweet paprika. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Румунія. Основні складники: яловичий фарш, часник, харчова сода, солодка паприка. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var g=[{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:12,i:[[`ground-beef`,500,`g`],[`garlic`,5,`clove`],[`baking-soda`,3,`g`],[`sweet-paprika`,7,`g`],[`ground-black-pepper`,null,`to_taste`],[`table-salt`,null,`to_taste`],[`water`,80,`ml`]]},{en:`Cool the prepared ingredients promptly, then refrigerate for about 45 minutes until properly chilled.`,ua:`Швидко охолодіть підготовлені складники, потім поставте в холодильник приблизно на 45 хвилин.`,t:[`rapid-chilling`],m:45,i:[]},{en:`Grill over medium-high heat for about 15 minutes, turning regularly until charred outside and safely cooked inside.`,ua:`Смажте на грилі на середньо-сильному жарі приблизно 15 хвилин, регулярно перевертаючи до рум’яної скоринки та повної готовності всередині.`,t:[`grilling`],m:15,i:[[`sunflower-oil`,20,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`dijon-mustard`,50,`g`]]}];var u={slug:n,id:t,country:`RO`,region:r,servings:4,minutes:74,title:s,text:d,steps:g};export{a as country,u as default,t as id,o as minutes,r as region,l as servings,n as slug,g as steps,d as text,s as title};